16 `include "common_cells/registers.svh"
17 
18 module fpnew_fma_multi #(
19   parameter fpnew_pkg::fmt_logic_t   FpFmtConfig = '1,
20   parameter int unsigned             NumPipeRegs = 0,
21   parameter fpnew_pkg::pipe_config_t PipeConfig  = fpnew_pkg::BEFORE,
22   parameter type                     TagType     = logic,
23   parameter type                     AuxType     = logic,
24   // Do not change
25   localparam int unsigned WIDTH       = fpnew_pkg::max_fp_width(FpFmtConfig),
26   localparam int unsigned NUM_FORMATS = fpnew_pkg::NUM_FP_FORMATS,
27   localparam int unsigned ExtRegEnaWidth = NumPipeRegs == 0 ? 1 : NumPipeRegs
28 ) (
29   input  logic                        clk_i,
30   input  logic                        rst_ni,
31   // Input signals
32   input  logic [2:0][WIDTH-1:0]       operands_i, // 3 operands
33   input  logic [NUM_FORMATS-1:0][2:0] is_boxed_i, // 3 operands
34   input  fpnew_pkg::roundmode_e       rnd_mode_i,
35   input  fpnew_pkg::operation_e       op_i,
36   input  logic                        op_mod_i,
37   input  fpnew_pkg::fp_format_e       src_fmt_i, // format of the multiplicands
38   input  fpnew_pkg::fp_format_e       dst_fmt_i, // format of the addend and result
39   input  TagType                      tag_i,
40   input  logic                        mask_i,
41   input  AuxType                      aux_i,
42   // Input Handshake
43   input  logic                        in_valid_i,
44   output logic                        in_ready_o,
45   input  logic                        flush_i,
46   // Output signals
47   output logic [WIDTH-1:0]            result_o,
48   output fpnew_pkg::status_t          status_o,
49   output logic                        extension_bit_o,
50   output TagType                      tag_o,
51   output logic                        mask_o,
52   output AuxType                      aux_o,
53   // Output handshake
54   output logic                        out_valid_o,
55   input  logic                        out_ready_i,
56   // Indication of valid data in flight
57   output logic                        busy_o,
58   // External register enable override
59   input  logic [ExtRegEnaWidth-1:0]   reg_ena_i
60 );
61 
62   // ----------
63   // Constants
64   // ----------
65   // The super-format that can hold all formats
66   localparam fpnew_pkg::fp_encoding_t SUPER_FORMAT = fpnew_pkg::super_format(FpFmtConfig);
67 
68   localparam int unsigned SUPER_EXP_BITS = SUPER_FORMAT.exp_bits;
69   localparam int unsigned SUPER_MAN_BITS = SUPER_FORMAT.man_bits;
70 
71   // Precision bits 'p' include the implicit bit
72   localparam int unsigned PRECISION_BITS = SUPER_MAN_BITS + 1;
73   // The lower 2p+3 bits of the internal FMA result will be needed for leading-zero detection
74   localparam int unsigned LOWER_SUM_WIDTH  = 2 * PRECISION_BITS + 3;
75   localparam int unsigned LZC_RESULT_WIDTH = $clog2(LOWER_SUM_WIDTH);
76   // Internal exponent width of FMA must accomodate all meaningful exponent values in order to avoid
77   // datapath leakage. This is either given by the exponent bits or the width of the LZC result.
78   // In most reasonable FP formats the internal exponent will be wider than the LZC result.
79   localparam int unsigned EXP_WIDTH = fpnew_pkg::maximum(SUPER_EXP_BITS + 2, LZC_RESULT_WIDTH);
80   // Shift amount width: maximum internal mantissa size is 3p+4 bits
81   localparam int unsigned SHIFT_AMOUNT_WIDTH = $clog2(3 * PRECISION_BITS + 5);
82   // Pipelines
83   localparam NUM_INP_REGS = PipeConfig == fpnew_pkg::BEFORE
84                             ? NumPipeRegs
85                             : (PipeConfig == fpnew_pkg::DISTRIBUTED
86                                ? ((NumPipeRegs + 1) / 3) // Second to get distributed regs
87                                : 0); // no regs here otherwise
88   localparam NUM_MID_REGS = PipeConfig == fpnew_pkg::INSIDE
89                           ? NumPipeRegs
90                           : (PipeConfig == fpnew_pkg::DISTRIBUTED
91                              ? ((NumPipeRegs + 2) / 3) // First to get distributed regs
92                              : 0); // no regs here otherwise
93   localparam NUM_OUT_REGS = PipeConfig == fpnew_pkg::AFTER
94                             ? NumPipeRegs
95                             : (PipeConfig == fpnew_pkg::DISTRIBUTED
96                                ? (NumPipeRegs / 3) // Last to get distributed regs
97                                : 0); // no regs here otherwise
98 
99   // ----------------
100   // Type definition
101   // ----------------
102   typedef struct packed {
103     logic                      sign;
104     logic [SUPER_EXP_BITS-1:0] exponent;
105     logic [SUPER_MAN_BITS-1:0] mantissa;
106   } fp_t;
107 
108   // ---------------
109   // Input pipeline
110   // ---------------
111   // Selected pipeline output signals as non-arrays
112   logic [2:0][WIDTH-1:0] operands_q;
113   fpnew_pkg::fp_format_e src_fmt_q;
114   fpnew_pkg::fp_format_e dst_fmt_q;
115 
116   // Input pipeline signals, index i holds signal after i register stages
117   logic                  [0:NUM_INP_REGS][2:0][WIDTH-1:0]       inp_pipe_operands_q;
118   logic                  [0:NUM_INP_REGS][NUM_FORMATS-1:0][2:0] inp_pipe_is_boxed_q;
119   fpnew_pkg::roundmode_e [0:NUM_INP_REGS]                       inp_pipe_rnd_mode_q;
120   fpnew_pkg::operation_e [0:NUM_INP_REGS]                       inp_pipe_op_q;
121   logic                  [0:NUM_INP_REGS]                       inp_pipe_op_mod_q;
122   fpnew_pkg::fp_format_e [0:NUM_INP_REGS]                       inp_pipe_src_fmt_q;
123   fpnew_pkg::fp_format_e [0:NUM_INP_REGS]                       inp_pipe_dst_fmt_q;
124   TagType                [0:NUM_INP_REGS]                       inp_pipe_tag_q;
125   logic                  [0:NUM_INP_REGS]                       inp_pipe_mask_q;
126   AuxType                [0:NUM_INP_REGS]                       inp_pipe_aux_q;
127   logic                  [0:NUM_INP_REGS]                       inp_pipe_valid_q;
128   // Ready signal is combinatorial for all stages
129   logic [0:NUM_INP_REGS] inp_pipe_ready;
130 
131   // Input stage: First element of pipeline is taken from inputs
132   assign inp_pipe_operands_q[0] = operands_i;
133   assign inp_pipe_is_boxed_q[0] = is_boxed_i;
134   assign inp_pipe_rnd_mode_q[0] = rnd_mode_i;
135   assign inp_pipe_op_q[0]       = op_i;
136   assign inp_pipe_op_mod_q[0]   = op_mod_i;
137   assign inp_pipe_src_fmt_q[0]  = src_fmt_i;
138   assign inp_pipe_dst_fmt_q[0]  = dst_fmt_i;
139   assign inp_pipe_tag_q[0]      = tag_i;
140   assign inp_pipe_mask_q[0]     = mask_i;
141   assign inp_pipe_aux_q[0]      = aux_i;
142   assign inp_pipe_valid_q[0]    = in_valid_i;
143   // Input stage: Propagate pipeline ready signal to updtream circuitry
144   assign in_ready_o = inp_pipe_ready[0];
145   // Generate the register stages
146   for (genvar i = 0; i < NUM_INP_REGS; i++) begin : gen_input_pipeline
147     // Internal register enable for this stage
148     logic reg_ena;
149     // Determine the ready signal of the current stage - advance the pipeline:
150     // 1. if the next stage is ready for our data
151     // 2. if the next stage only holds a bubble (not valid) -> we can pop it
152     assign inp_pipe_ready[i] = inp_pipe_ready[i+1] | ~inp_pipe_valid_q[i+1];
153     // Valid: enabled by ready signal, synchronous clear with the flush signal
154     `FFLARNC(inp_pipe_valid_q[i+1], inp_pipe_valid_q[i], inp_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
155     // Enable register if pipleine ready and a valid data item is present
156     assign reg_ena = (inp_pipe_ready[i] & inp_pipe_valid_q[i]) | reg_ena_i[i];
157     // Generate the pipeline registers within the stages, use enable-registers
158     `FFL(inp_pipe_operands_q[i+1], inp_pipe_operands_q[i], reg_ena, '0)
159     `FFL(inp_pipe_is_boxed_q[i+1], inp_pipe_is_boxed_q[i], reg_ena, '0)
160     `FFL(inp_pipe_rnd_mode_q[i+1], inp_pipe_rnd_mode_q[i], reg_ena, fpnew_pkg::RNE)
161     `FFL(inp_pipe_op_q[i+1],       inp_pipe_op_q[i],       reg_ena, fpnew_pkg::FMADD)
162     `FFL(inp_pipe_op_mod_q[i+1],   inp_pipe_op_mod_q[i],   reg_ena, '0)
163     `FFL(inp_pipe_src_fmt_q[i+1],  inp_pipe_src_fmt_q[i],  reg_ena, fpnew_pkg::fp_format_e'(0))
164     `FFL(inp_pipe_dst_fmt_q[i+1],  inp_pipe_dst_fmt_q[i],  reg_ena, fpnew_pkg::fp_format_e'(0))
165     `FFL(inp_pipe_tag_q[i+1],      inp_pipe_tag_q[i],      reg_ena, TagType'('0))
166     `FFL(inp_pipe_mask_q[i+1],     inp_pipe_mask_q[i],     reg_ena, '0)
167     `FFL(inp_pipe_aux_q[i+1],      inp_pipe_aux_q[i],      reg_ena, AuxType'('0))
168   end
169   // Output stage: assign selected pipe outputs to signals for later use
170   assign operands_q = inp_pipe_operands_q[NUM_INP_REGS];
171   assign src_fmt_q  = inp_pipe_src_fmt_q[NUM_INP_REGS];
172   assign dst_fmt_q  = inp_pipe_dst_fmt_q[NUM_INP_REGS];
173 
174   // -----------------
175   // Input processing
176   // -----------------
177   logic        [NUM_FORMATS-1:0][2:0]                     fmt_sign;
178   logic signed [NUM_FORMATS-1:0][2:0][SUPER_EXP_BITS-1:0] fmt_exponent;
179   logic        [NUM_FORMATS-1:0][2:0][SUPER_MAN_BITS-1:0] fmt_mantissa;
180 
181   fpnew_pkg::fp_info_t [NUM_FORMATS-1:0][2:0] info_q;
182 
183   // FP Input initialization
184   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : fmt_init_inputs
185     // Set up some constants
186     localparam int unsigned FP_WIDTH = fpnew_pkg::fp_width(fpnew_pkg::fp_format_e'(fmt));
187     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
188     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
189 
190     if (FpFmtConfig[fmt]) begin : active_format
191       logic [2:0][FP_WIDTH-1:0] trimmed_ops;
192 
193       // Classify input
194       fpnew_classifier #(
195         .FpFormat    ( fpnew_pkg::fp_format_e'(fmt) ),
196         .NumOperands ( 3                            )
197       ) i_fpnew_classifier (
198         .operands_i ( trimmed_ops                            ),
199         .is_boxed_i ( inp_pipe_is_boxed_q[NUM_INP_REGS][fmt] ),
200         .info_o     ( info_q[fmt]                            )
201       );
202       for (genvar op = 0; op < 3; op++) begin : gen_operands
203         assign trimmed_ops[op]       = operands_q[op][FP_WIDTH-1:0];
204         assign fmt_sign[fmt][op]     = operands_q[op][FP_WIDTH-1];
205         assign fmt_exponent[fmt][op] = signed'({1'b0, operands_q[op][MAN_BITS+:EXP_BITS]});
206         assign fmt_mantissa[fmt][op] = {info_q[fmt][op].is_normal, operands_q[op][MAN_BITS-1:0]} <<
207                                        (SUPER_MAN_BITS - MAN_BITS); // move to left of mantissa
208       end
209     end else begin : inactive_format
210       assign info_q[fmt]                 = '{default: fpnew_pkg::DONT_CARE}; // format disabled
211       assign fmt_sign[fmt]               = fpnew_pkg::DONT_CARE;             // format disabled
212       assign fmt_exponent[fmt]           = '{default: fpnew_pkg::DONT_CARE}; // format disabled
213       assign fmt_mantissa[fmt]           = '{default: fpnew_pkg::DONT_CARE}; // format disabled
214     end
215   end
216 
217   fp_t                 operand_a, operand_b, operand_c;
218   fpnew_pkg::fp_info_t info_a,    info_b,    info_c;
219 
220   // Operation selection and operand adjustment
221   // | \c op_q  | \c op_mod_q | Operation Adjustment
222   // |:--------:|:-----------:|---------------------
223   // | FMADD    | \c 0        | FMADD: none
224   // | FMADD    | \c 1        | FMSUB: Invert sign of operand C
225   // | FNMSUB   | \c 0        | FNMSUB: Invert sign of operand A
226   // | FNMSUB   | \c 1        | FNMADD: Invert sign of operands A and C
227   // | ADD      | \c 0        | ADD: Set operand A to +1.0
228   // | ADD      | \c 1        | SUB: Set operand A to +1.0, invert sign of operand C
229   // | MUL      | \c 0        | MUL: Set operand C to +0.0 or -0.0 depending on the rounding mode
230   // | *others* | \c -        | *invalid*
231   // \note \c op_mod_q always inverts the sign of the addend.
232   always_comb begin : op_select
233 
234     // Default assignments - packing-order-agnostic
235     operand_a = {fmt_sign[src_fmt_q][0], fmt_exponent[src_fmt_q][0], fmt_mantissa[src_fmt_q][0]};
236     operand_b = {fmt_sign[src_fmt_q][1], fmt_exponent[src_fmt_q][1], fmt_mantissa[src_fmt_q][1]};
237     operand_c = {fmt_sign[dst_fmt_q][2], fmt_exponent[dst_fmt_q][2], fmt_mantissa[dst_fmt_q][2]};
238     info_a    = info_q[src_fmt_q][0];
239     info_b    = info_q[src_fmt_q][1];
240     info_c    = info_q[dst_fmt_q][2];
241 
242     // op_mod_q inverts sign of operand C
243     operand_c.sign = operand_c.sign ^ inp_pipe_op_mod_q[NUM_INP_REGS];
244 
245     unique case (inp_pipe_op_q[NUM_INP_REGS])
246       fpnew_pkg::FMADD:  ; // do nothing
247       fpnew_pkg::FNMSUB: operand_a.sign = ~operand_a.sign; // invert sign of product
248       fpnew_pkg::ADD: begin // Set multiplicand to +1
249         operand_a = '{sign: 1'b0, exponent: fpnew_pkg::bias(src_fmt_q), mantissa: '0};
250         info_a    = '{is_normal: 1'b1, is_boxed: 1'b1, default: 1'b0}; //normal, boxed value.
251       end
252       fpnew_pkg::MUL: begin // Set addend to +0 or -0, depending whether the rounding mode is RDN
253         if (inp_pipe_rnd_mode_q[NUM_INP_REGS] == fpnew_pkg::RDN)
254           operand_c = '{sign: 1'b0, exponent: '0, mantissa: '0};
255         else
256           operand_c = '{sign: 1'b1, exponent: '0, mantissa: '0};
257         info_c    = '{is_zero: 1'b1, is_boxed: 1'b1, default: 1'b0}; //zero, boxed value.
258       end
259       default: begin // propagate don't cares
260         operand_a  = '{default: fpnew_pkg::DONT_CARE};
261         operand_b  = '{default: fpnew_pkg::DONT_CARE};
262         operand_c  = '{default: fpnew_pkg::DONT_CARE};
263         info_a     = '{default: fpnew_pkg::DONT_CARE};
264         info_b     = '{default: fpnew_pkg::DONT_CARE};
265         info_c     = '{default: fpnew_pkg::DONT_CARE};
266       end
267     endcase
268   end
269 
270   // ---------------------
271   // Input classification
272   // ---------------------
273   logic any_operand_inf;
274   logic any_operand_nan;
275   logic signalling_nan;
276   logic effective_subtraction;
277   logic tentative_sign;
278 
279   // Reduction for special case handling
280   assign any_operand_inf = (| {info_a.is_inf,        info_b.is_inf,        info_c.is_inf});
281   assign any_operand_nan = (| {info_a.is_nan,        info_b.is_nan,        info_c.is_nan});
282   assign signalling_nan  = (| {info_a.is_signalling, info_b.is_signalling, info_c.is_signalling});
283   // Effective subtraction in FMA occurs when product and addend signs differ
284   assign effective_subtraction = operand_a.sign ^ operand_b.sign ^ operand_c.sign;
285   // The tentative sign of the FMA shall be the sign of the product
286   assign tentative_sign = operand_a.sign ^ operand_b.sign;
287 
288   // ----------------------
289   // Special case handling
290   // ----------------------
291   logic [WIDTH-1:0]   special_result;
292   fpnew_pkg::status_t special_status;
293   logic               result_is_special;
294 
295   logic [NUM_FORMATS-1:0][WIDTH-1:0]    fmt_special_result;
296   fpnew_pkg::status_t [NUM_FORMATS-1:0] fmt_special_status;
297   logic [NUM_FORMATS-1:0]               fmt_result_is_special;
298 
299 
300   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_special_results
301     // Set up some constants
302     localparam int unsigned FP_WIDTH = fpnew_pkg::fp_width(fpnew_pkg::fp_format_e'(fmt));
303     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
304     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
305 
306     localparam logic [EXP_BITS-1:0] QNAN_EXPONENT = '1;
307     localparam logic [MAN_BITS-1:0] QNAN_MANTISSA = 2**(MAN_BITS-1);
308     localparam logic [MAN_BITS-1:0] ZERO_MANTISSA = '0;
309 
310     if (FpFmtConfig[fmt]) begin : active_format
311       always_comb begin : special_results
312         logic [FP_WIDTH-1:0] special_res;
313 
314         // Default assignment
315         special_res                = {1'b0, QNAN_EXPONENT, QNAN_MANTISSA}; // qNaN
316         fmt_special_status[fmt]    = '0;
317         fmt_result_is_special[fmt] = 1'b0;
318 
319         // Handle potentially mixed nan & infinity input => important for the case where infinity and
320         // zero are multiplied and added to a qnan.
321         // RISC-V mandates raising the NV exception in these cases:
322         // (inf * 0) + c or (0 * inf) + c INVALID, no matter c (even quiet NaNs)
323         if ((info_a.is_inf && info_b.is_zero) || (info_a.is_zero && info_b.is_inf)) begin
324           fmt_result_is_special[fmt] = 1'b1; // bypass FMA, output is the canonical qNaN
325           fmt_special_status[fmt].NV = 1'b1; // invalid operation
326         // NaN Inputs cause canonical quiet NaN at the output and maybe invalid OP
327         end else if (any_operand_nan) begin
328           fmt_result_is_special[fmt] = 1'b1;           // bypass FMA, output is the canonical qNaN
329           fmt_special_status[fmt].NV = signalling_nan; // raise the invalid operation flag if signalling
330         // Special cases involving infinity
331         end else if (any_operand_inf) begin
332           fmt_result_is_special[fmt] = 1'b1; // bypass FMA
333           // Effective addition of opposite infinities (±inf - ±inf) is invalid!
334           if ((info_a.is_inf || info_b.is_inf) && info_c.is_inf && effective_subtraction)
335             fmt_special_status[fmt].NV = 1'b1; // invalid operation
336           // Handle cases where output will be inf because of inf product input
337           else if (info_a.is_inf || info_b.is_inf) begin
338             // Result is infinity with the sign of the product
339             special_res = {operand_a.sign ^ operand_b.sign, QNAN_EXPONENT, ZERO_MANTISSA};
340           // Handle cases where the addend is inf
341           end else if (info_c.is_inf) begin
342             // Result is inifinity with sign of the addend (= operand_c)
343             special_res = {operand_c.sign, QNAN_EXPONENT, ZERO_MANTISSA};
344           end
345         end
346         // Initialize special result with ones (NaN-box)
347         fmt_special_result[fmt]               = '1;
348         fmt_special_result[fmt][FP_WIDTH-1:0] = special_res;
349       end
350     end else begin : inactive_format
351       assign fmt_special_result[fmt] = '{default: fpnew_pkg::DONT_CARE};
352       assign fmt_special_status[fmt] = '0;
353       assign fmt_result_is_special[fmt] = 1'b0;
354     end
355   end
356 
357   // Detect special case from source format, I2F casts don't produce a special result
358   assign result_is_special = fmt_result_is_special[dst_fmt_q]; // they're all the same
359   // Signalling input NaNs raise invalid flag, otherwise no flags set
360   assign special_status = fmt_special_status[dst_fmt_q];
361   // Assemble result according to destination format
362   assign special_result = fmt_special_result[dst_fmt_q]; // destination format
363 
364   // ---------------------------
365   // Initial exponent data path
366   // ---------------------------
367   logic signed [EXP_WIDTH-1:0] exponent_a, exponent_b, exponent_c;
368   logic signed [EXP_WIDTH-1:0] exponent_addend, exponent_product, exponent_difference;
369   logic signed [EXP_WIDTH-1:0] tentative_exponent;
370 
371   // Zero-extend exponents into signed container - implicit width extension
372   assign exponent_a = signed'({1'b0, operand_a.exponent});
373   assign exponent_b = signed'({1'b0, operand_b.exponent});
374   assign exponent_c = signed'({1'b0, operand_c.exponent});
375 
376   // Calculate internal exponents from encoded values. Real exponents are (ex = Ex - bias + 1 - nx)
377   // with Ex the encoded exponent and nx the implicit bit. Internal exponents are biased to dst fmt.
378   assign exponent_addend = signed'(exponent_c + $signed({1'b0, ~info_c.is_normal})); // 0 as subnorm
379   // Biased product exponent is the sum of encoded exponents minus the bias.
380   assign exponent_product = (info_a.is_zero || info_b.is_zero) // in case the product is zero, set minimum exp.
381                             ? 2 - signed'(fpnew_pkg::bias(dst_fmt_q))
382                             : signed'(exponent_a + info_a.is_subnormal
383                                       + exponent_b + info_b.is_subnormal
384                                       - 2*signed'(fpnew_pkg::bias(src_fmt_q))
385                                       + signed'(fpnew_pkg::bias(dst_fmt_q))); // rebias for dst fmt
386   // Exponent difference is the addend exponent minus the product exponent
387   assign exponent_difference = exponent_addend - exponent_product;
388   // The tentative exponent will be the larger of the product or addend exponent
389   assign tentative_exponent = (exponent_difference > 0) ? exponent_addend : exponent_product;
390 
391   // Shift amount for addend based on exponents (unsigned as only right shifts)
392   logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt;
393 
394   always_comb begin : addend_shift_amount
395     // Product-anchored case, saturated shift (addend is only in the sticky bit)
396     if (exponent_difference <= signed'(-2 * PRECISION_BITS - 1))
397       addend_shamt = 3 * PRECISION_BITS + 4;
398     // Addend and product will have mutual bits to add
399     else if (exponent_difference <= signed'(PRECISION_BITS + 2))
400       addend_shamt = unsigned'(signed'(PRECISION_BITS) + 3 - exponent_difference);
401     // Addend-anchored case, saturated shift (product is only in the sticky bit)
402     else
403       addend_shamt = 0;
404   end
405 
406   // ------------------
407   // Product data path
408   // ------------------
409   logic [PRECISION_BITS-1:0]   mantissa_a, mantissa_b, mantissa_c;
410   logic [2*PRECISION_BITS-1:0] product;             // the p*p product is 2p bits wide
411   logic [3*PRECISION_BITS+3:0] product_shifted;     // addends are 3p+4 bit wide (including G/R)
412 
413   // Add implicit bits to mantissae
414   assign mantissa_a = {info_a.is_normal, operand_a.mantissa};
415   assign mantissa_b = {info_b.is_normal, operand_b.mantissa};
416   assign mantissa_c = {info_c.is_normal, operand_c.mantissa};
417 
418   // Mantissa multiplier (a*b)
419   assign product = mantissa_a * mantissa_b;
420 
421   // Product is placed into a 3p+4 bit wide vector, padded with 2 bits for round and sticky:
422   // | 000...000 | product | RS |
423   //  <-  p+2  -> <-  2p -> < 2>
424   assign product_shifted = product << 2; // constant shift
425 
426   // -----------------
427   // Addend data path
428   // -----------------
429   logic [3*PRECISION_BITS+3:0] addend_after_shift;  // upper 3p+4 bits are needed to go on
430   logic [PRECISION_BITS-1:0]   addend_sticky_bits;  // up to p bit of shifted addend are sticky
431   logic                        sticky_before_add;   // they are compressed into a single sticky bit
432   logic [3*PRECISION_BITS+3:0] addend_shifted;      // addends are 3p+4 bit wide (including G/R)
433   logic                        inject_carry_in;     // inject carry for subtractions if needed
434 
435   // In parallel, the addend is right-shifted according to the exponent difference. Up to p bits are
436   // shifted out and compressed into a sticky bit.
437   // BEFORE THE SHIFT:
438   // | mantissa_c | 000..000 |
439   //  <-    p   -> <- 3p+4 ->
440   // AFTER THE SHIFT:
441   // | 000..........000 | mantissa_c | 000...............0GR |  sticky bits  |
442   //  <- addend_shamt -> <-    p   -> <- 2p+4-addend_shamt -> <-  up to p  ->
443   assign {addend_after_shift, addend_sticky_bits} =
444       (mantissa_c << (3 * PRECISION_BITS + 4)) >> addend_shamt;
445 
446   assign sticky_before_add     = (| addend_sticky_bits);
447 
448   // In case of a subtraction, the addend is inverted
449   assign addend_shifted = (effective_subtraction) ? ~addend_after_shift : addend_after_shift;
450   assign inject_carry_in = effective_subtraction & ~sticky_before_add;
451 
452   // ------
453   // Adder
454   // ------
455   logic [3*PRECISION_BITS+4:0] sum_raw;   // added one bit for the carry
456   logic                        sum_carry; // observe carry bit from sum for sign fixing
457   logic [3*PRECISION_BITS+3:0] sum;       // discard carry as sum won't overflow
458   logic                        final_sign;
459 
460   //Mantissa adder (ab+c). In normal addition, it cannot overflow.
461   assign sum_raw = product_shifted + addend_shifted + inject_carry_in;
462   assign sum_carry = sum_raw[3*PRECISION_BITS+4];
463 
464   // Complement negative sum (can only happen in subtraction -> overflows for positive results)
465   assign sum        = (effective_subtraction && ~sum_carry) ? -sum_raw : sum_raw;
466 
467   // In case of a mispredicted subtraction result, do a sign flip
468   assign final_sign = (effective_subtraction && (sum_carry == tentative_sign))
469                       ? 1'b1
470                       : (effective_subtraction ? 1'b0 : tentative_sign);
471 
472   // ---------------
473   // Internal pipeline
474   // ---------------
475   // Pipeline output signals as non-arrays
476   logic                          effective_subtraction_q;
477   logic signed [EXP_WIDTH-1:0]   exponent_product_q;
478   logic signed [EXP_WIDTH-1:0]   exponent_difference_q;
479   logic signed [EXP_WIDTH-1:0]   tentative_exponent_q;
