562   assign effective_subtraction_q = mid_pipe_eff_sub_q[NUM_MID_REGS];
563   assign exponent_product_q      = mid_pipe_exp_prod_q[NUM_MID_REGS];
564   assign exponent_difference_q   = mid_pipe_exp_diff_q[NUM_MID_REGS];
565   assign tentative_exponent_q    = mid_pipe_tent_exp_q[NUM_MID_REGS];
566   assign addend_shamt_q          = mid_pipe_add_shamt_q[NUM_MID_REGS];
567   assign sticky_before_add_q     = mid_pipe_sticky_q[NUM_MID_REGS];
568   assign sum_q                   = mid_pipe_sum_q[NUM_MID_REGS];
569   assign final_sign_q            = mid_pipe_final_sign_q[NUM_MID_REGS];
570   assign rnd_mode_q              = mid_pipe_rnd_mode_q[NUM_MID_REGS];
