576   // --------------
577   // Normalization
578   // --------------
579   logic        [LOWER_SUM_WIDTH-1:0]  sum_lower;              // lower 2p+3 bits of sum are searched
580   logic        [LZC_RESULT_WIDTH-1:0] leading_zero_count;     // the number of leading zeroes
581   logic signed [LZC_RESULT_WIDTH:0]   leading_zero_count_sgn; // signed leading-zero count
582   logic                               lzc_zeroes;             // in case only zeroes found
583 
584   logic        [SHIFT_AMOUNT_WIDTH-1:0] norm_shamt; // Normalization shift amount
585   logic signed [EXP_WIDTH-1:0]          normalized_exponent;
586 
587   logic [3*PRECISION_BITS+4:0] sum_shifted;       // result after first normalization shift
588   logic [PRECISION_BITS:0]     final_mantissa;    // final mantissa before rounding with round bit
589   logic [2*PRECISION_BITS+2:0] sum_sticky_bits;   // remaining 2p+3 sticky bits after normalization
590   logic                        sticky_after_norm; // sticky bit after normalization
591 
592   logic signed [EXP_WIDTH-1:0] final_exponent;
593 
594   assign sum_lower = sum_q[LOWER_SUM_WIDTH-1:0];
595 
596   // Leading zero counter for cancellations
597   lzc #(
598     .WIDTH ( LOWER_SUM_WIDTH ),
599     .MODE  ( 1               ) // MODE = 1 counts leading zeroes
600   ) i_lzc (
601     .in_i    ( sum_lower          ),
602     .cnt_o   ( leading_zero_count ),
603     .empty_o ( lzc_zeroes         )
604   );
605 
606   assign leading_zero_count_sgn = signed'({1'b0, leading_zero_count});
607 
608   // Normalization shift amount based on exponents and LZC (unsigned as only left shifts)
609   always_comb begin : norm_shift_amount
610     // Product-anchored case or cancellations require LZC
611     if ((exponent_difference_q <= 0) || (effective_subtraction_q && (exponent_difference_q <= 2))) begin
612       // Normal result (biased exponent > 0 and not a zero)
613       if ((exponent_product_q - leading_zero_count_sgn + 1 >= 0) && !lzc_zeroes) begin
614         // Undo initial product shift, remove the counted zeroes
615         norm_shamt          = PRECISION_BITS + 2 + leading_zero_count;
616         normalized_exponent = exponent_product_q - leading_zero_count_sgn + 1; // account for shift
617       // Subnormal result
618       end else begin
619         // Cap the shift distance to align mantissa with minimum exponent
620         norm_shamt          = unsigned'(signed'(PRECISION_BITS + 2 + exponent_product_q));
621         normalized_exponent = 0; // subnormals encoded as 0
622       end
623     // Addend-anchored case
624     end else begin
625       norm_shamt          = addend_shamt_q; // Undo the initial shift
626       normalized_exponent = tentative_exponent_q;
627     end
628   end
629 
630   // Do the large normalization shift
631   assign sum_shifted       = sum_q << norm_shamt;
632 
633   // The addend-anchored case needs a 1-bit normalization since the leading-one can be to the left
634   // or right of the (non-carry) MSB of the sum.
635   always_comb begin : small_norm
636     // Default assignment, discarding carry bit
637     {final_mantissa, sum_sticky_bits} = sum_shifted;
638     final_exponent                    = normalized_exponent;
639 
640     // The normalized sum has overflown, align right and fix exponent
641     if (sum_shifted[3*PRECISION_BITS+4]) begin // check the carry bit
642       {final_mantissa, sum_sticky_bits} = sum_shifted >> 1;
643       final_exponent                    = normalized_exponent + 1;
644     // The normalized sum is normal, nothing to do
645     end else if (sum_shifted[3*PRECISION_BITS+3]) begin // check the sum MSB
646       // do nothing
647     // The normalized sum is still denormal, align left - unless the result is not already subnormal
648     end else if (normalized_exponent > 1) begin
649       {final_mantissa, sum_sticky_bits} = sum_shifted << 1;
650       final_exponent                    = normalized_exponent - 1;
651     // Otherwise we're denormal
652     end else begin
653       final_exponent = '0;
654     end
655   end
656 
657   // Update the sticky bit with the shifted-out bits
658   assign sticky_after_norm = (| {sum_sticky_bits}) | sticky_before_add_q;
659 
660   // ----------------------------
661   // Rounding and classification
662   // ----------------------------
663   logic                                     pre_round_sign;
664   logic [SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] pre_round_abs; // absolute value of result before rounding
665   logic [1:0]                               round_sticky_bits;
666 
667   logic of_before_round, of_after_round; // overflow
668   logic uf_before_round, uf_after_round; // underflow
669 
670   logic [NUM_FORMATS-1:0][SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] fmt_pre_round_abs; // per format
671   logic [NUM_FORMATS-1:0][1:0]                               fmt_round_sticky_bits;
672 
673   logic [NUM_FORMATS-1:0]                                    fmt_of_after_round;
674   logic [NUM_FORMATS-1:0]                                    fmt_uf_after_round;
675 
676   logic                                     rounded_sign;
677   logic [SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] rounded_abs; // absolute value of result after rounding
678   logic                                     result_zero;
679 
680   // Classification before round. RISC-V mandates checking underflow AFTER rounding!
681   assign of_before_round = final_exponent >= 2**(fpnew_pkg::exp_bits(dst_fmt_q2))-1; // infinity exponent is all ones
682   assign uf_before_round = final_exponent == 0;               // exponent for subnormals capped to 0
683 
684   // Pack exponent and mantissa into proper rounding form
685   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_res_assemble
686     // Set up some constants
687     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
688     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
689 
690     logic [EXP_BITS-1:0] pre_round_exponent;
691     logic [MAN_BITS-1:0] pre_round_mantissa;
692 
693     if (FpFmtConfig[fmt]) begin : active_format
694 
695       assign pre_round_exponent = (of_before_round) ? 2**EXP_BITS-2 : final_exponent[EXP_BITS-1:0];
696       assign pre_round_mantissa = (of_before_round) ? '1 : final_mantissa[SUPER_MAN_BITS-:MAN_BITS];
697       // Assemble result before rounding. In case of overflow, the largest normal value is set.
698       assign fmt_pre_round_abs[fmt] = {pre_round_exponent, pre_round_mantissa}; // 0-extend
699 
700       // Round bit is after mantissa (1 in case of overflow for rounding)
701       assign fmt_round_sticky_bits[fmt][1] = final_mantissa[SUPER_MAN_BITS-MAN_BITS] |
702                                              of_before_round;
703 
704       // remaining bits in mantissa to sticky (1 in case of overflow for rounding)
705       if (MAN_BITS < SUPER_MAN_BITS) begin : narrow_sticky
706         assign fmt_round_sticky_bits[fmt][0] = (| final_mantissa[SUPER_MAN_BITS-MAN_BITS-1:0]) |
707                                                sticky_after_norm | of_before_round;
708       end else begin : normal_sticky
709         assign fmt_round_sticky_bits[fmt][0] = sticky_after_norm | of_before_round;
710       end
711     end else begin : inactive_format
712       assign fmt_pre_round_abs[fmt] = '{default: fpnew_pkg::DONT_CARE};
713       assign fmt_round_sticky_bits[fmt] = '{default: fpnew_pkg::DONT_CARE};
714     end
715   end
716 
717   // Assemble result before rounding. In case of overflow, the largest normal value is set.
718   assign pre_round_sign     = final_sign_q;
719   assign pre_round_abs      = fmt_pre_round_abs[dst_fmt_q2];
720 
721   // In case of overflow, the round and sticky bits are set for proper rounding
722   assign round_sticky_bits  = fmt_round_sticky_bits[dst_fmt_q2];
723 
724   // Perform the rounding
725   fpnew_rounding #(
726     .AbsWidth ( SUPER_EXP_BITS + SUPER_MAN_BITS )
727   ) i_fpnew_rounding (
728     .abs_value_i             ( pre_round_abs           ),
729     .sign_i                  ( pre_round_sign          ),
730     .round_sticky_bits_i     ( round_sticky_bits       ),
731     .rnd_mode_i              ( rnd_mode_q              ),
732     .effective_subtraction_i ( effective_subtraction_q ),
733     .abs_rounded_o           ( rounded_abs             ),
734     .sign_o                  ( rounded_sign            ),
735     .exact_zero_o            ( result_zero             )
736   );
737 
738   logic [NUM_FORMATS-1:0][WIDTH-1:0] fmt_result;
739 
740   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_sign_inject
741     // Set up some constants
742     localparam int unsigned FP_WIDTH = fpnew_pkg::fp_width(fpnew_pkg::fp_format_e'(fmt));
743     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
744     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
745 
746     if (FpFmtConfig[fmt]) begin : active_format
747       always_comb begin : post_process
748         // detect of / uf        
749         fmt_uf_after_round[fmt] = (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '0) // denormal
750         || ((pre_round_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '0) && (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == 1) && 
751               ((round_sticky_bits != 2'b11) || (!sum_sticky_bits[MAN_BITS*2 + 4] && ((rnd_mode_i == fpnew_pkg::RNE) || (rnd_mode_i == fpnew_pkg::RMM)))));
752         fmt_of_after_round[fmt] = rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '1; // inf exp.
753 
754         // Assemble regular result, nan box short ones.
755         fmt_result[fmt]               = '1;
756         fmt_result[fmt][FP_WIDTH-1:0] = {rounded_sign, rounded_abs[EXP_BITS+MAN_BITS-1:0]};
757       end
758     end else begin : inactive_format
759       assign fmt_uf_after_round[fmt] = fpnew_pkg::DONT_CARE;
760       assign fmt_of_after_round[fmt] = fpnew_pkg::DONT_CARE;
761       assign fmt_result[fmt]         = '{default: fpnew_pkg::DONT_CARE};
762     end
763   end
764 
765   // Classification after rounding select by destination format
766   assign uf_after_round = fmt_uf_after_round[dst_fmt_q2];
767   assign of_after_round = fmt_of_after_round[dst_fmt_q2];
768 
769 
770   // -----------------
771   // Result selection
772   // -----------------
773   logic [WIDTH-1:0]     regular_result;
774   fpnew_pkg::status_t   regular_status;
775 
776   // Assemble regular result
777   assign regular_result = fmt_result[dst_fmt_q2];
778   assign regular_status.NV = 1'b0; // only valid cases are handled in regular path
779   assign regular_status.DZ = 1'b0; // no divisions
780   assign regular_status.OF = of_before_round | of_after_round;   // rounding can introduce overflow
781   assign regular_status.UF = uf_after_round & regular_status.NX; // only inexact results raise UF
782   assign regular_status.NX = (| round_sticky_bits) | of_before_round | of_after_round;
783 
784   // Final results for output pipeline
785   logic [WIDTH-1:0]   result_d;
786   fpnew_pkg::status_t status_d;
787 
788   // Select output depending on special case detection
789   assign result_d = result_is_special_q ? special_result_q : regular_result;
790   assign status_d = result_is_special_q ? special_status_q : regular_status;
791 
792   // ----------------
793   // Output Pipeline
794   // ----------------
795   // Output pipeline signals, index i holds signal after i register stages
796   logic               [0:NUM_OUT_REGS][WIDTH-1:0] out_pipe_result_q;
797   fpnew_pkg::status_t [0:NUM_OUT_REGS]            out_pipe_status_q;
798   TagType             [0:NUM_OUT_REGS]            out_pipe_tag_q;
799   logic               [0:NUM_OUT_REGS]            out_pipe_mask_q;
800   AuxType             [0:NUM_OUT_REGS]            out_pipe_aux_q;
801   logic               [0:NUM_OUT_REGS]            out_pipe_valid_q;
802   // Ready signal is combinatorial for all stages
803   logic [0:NUM_OUT_REGS] out_pipe_ready;
804 
805   // Input stage: First element of pipeline is taken from inputs
806   assign out_pipe_result_q[0] = result_d;
807   assign out_pipe_status_q[0] = status_d;
808   assign out_pipe_tag_q[0]    = mid_pipe_tag_q[NUM_MID_REGS];
809   assign out_pipe_mask_q[0]   = mid_pipe_mask_q[NUM_MID_REGS];
810   assign out_pipe_aux_q[0]    = mid_pipe_aux_q[NUM_MID_REGS];
811   assign out_pipe_valid_q[0]  = mid_pipe_valid_q[NUM_MID_REGS];
812   // Input stage: Propagate pipeline ready signal to inside pipe
813   assign mid_pipe_ready[NUM_MID_REGS] = out_pipe_ready[0];
814   // Generate the register stages
815   for (genvar i = 0; i < NUM_OUT_REGS; i++) begin : gen_output_pipeline
816     // Internal register enable for this stage
817     logic reg_ena;
